//! These fixtures were generated by executing the original Go implementation,
//! not by constructing expected JSON using this Rust implementation.
use serde_json::Value;
use ssb::{
    link,
    profile::{Dirs, State},
    render,
};

fn fixtures() -> Value {
    serde_json::from_str(include_str!("fixtures/upstream.json")).unwrap()
}
#[test]
fn original_go_node_outputs_match_rust() {
    let fixture = fixtures();
    for expected in fixture["nodes"].as_array().unwrap() {
        let raw = expected["raw"].as_str().unwrap();
        let actual = link::parse(raw).unwrap();
        assert_eq!(serde_json::to_value(actual).unwrap(), *expected, "{raw}");
    }
}
#[test]
fn original_go_configs_match_except_documented_dns_fixes() {
    let fixture = fixtures();
    let d = Dirs::new("/ssb-parity").unwrap();
    for (i, case) in fixture["configs"].as_array().unwrap().iter().enumerate() {
        let state: State = serde_json::from_value(case["state"].clone()).unwrap();
        let actual =
            render::build_for(&state, &d, case["host_ipv6"].as_bool().unwrap(), true).unwrap();
        // The fixture deliberately models Linux, including auto_redirect.
        // Paths are normalized so it remains useful on Windows runners.
        fn normalized(v: &mut Value) {
            match v {
                Value::String(s) if s.contains("ssb-parity") => {
                    if let Some(i) = s.find("ssb-parity") {
                        *s = format!("/{}", s[i..].replace('\\', "/"));
                    }
                }
                Value::Array(a) => {
                    for v in a {
                        normalized(v);
                    }
                }
                Value::Object(o) => {
                    for v in o.values_mut() {
                        normalized(v);
                    }
                }
                _ => {}
            }
        }
        let mut actual = actual;
        normalized(&mut actual);
        let mut expected = case["config"].clone();
        // Intentional improvement: real-IP DNS retains domains for routing.
        // Keep the immutable Go fixture, while comparing all other fields exactly.
        if !state.settings.fakeip {
            expected["dns"]["reverse_mapping"] = true.into();
        }
        // FakeIP cannot answer TXT/MX/HTTPS queries. Preserve custom proxy DNS
        // routing for those types with an adjacent real-DoH fallback rule.
        if state.settings.fakeip {
            if let Some(rules) = expected["dns"]["rules"].as_array_mut() {
                let mut migrated = vec![];
                for rule in rules.iter() {
                    if rule["server"] == "dns-fakeip" && rule.get("query_type").is_none() {
                        let mut address_rule = rule.clone();
                        let v6 = state.settings.ipv6 == "on"
                            || (state.settings.ipv6 == "auto" && case["host_ipv6"] == true);
                        address_rule["query_type"] = if v6 {
                            serde_json::json!(["A", "AAAA"])
                        } else {
                            serde_json::json!(["A"])
                        };
                        migrated.push(address_rule);
                        let mut fallback = rule.clone();
                        fallback["server"] = "dns-proxy".into();
                        migrated.push(fallback);
                    } else {
                        migrated.push(rule.clone());
                    }
                }
                *rules = migrated;
            }
        }
        normalized(&mut expected);
        assert_eq!(actual, expected, "original Go config case {i}");
    }
}
